int val = 42;
int next_val = 99;

// 1. Pointer to Const Data (Data Read-Only)
// const T* ptr;
const int* p_ro_data = &val;
p_ro_data = &next_val;      // Pointer can change
// *p_ro_data = 0;         // Error: Cannot modify data

// 2. Const Pointer (Address Fixed)
// T* const ptr;
int* const p_fixed_addr = &val;
*p_fixed_addr = 100;        // Data can change
// p_fixed_addr = &next_val; // Error: Cannot reassign pointer

// 3. Const Pointer to Const Data (Fully Immutable)
// const T* const ptr;
const int* const p_immutable = &val;
// Both reassignment and modification are invalid.

// Note on const placement:
// int const* p; // Same as const int* p;
// Read declaration backwards from variable name.
